import { getProducts } from '@/lib/products'

export default async function AdminInventoryPage() {
  const products = await getProducts()
  const inStock = products.filter((product) => product.inventory > 0)
  const outOfStock = products.filter((product) => product.inventory === 0)

  return (
    <main>
      <header>
        <h1>Inventory overview</h1>
        <p>Stock levels from the shared product catalog cache.</p>
      </header>

      <section>
        <h2>In stock ({inStock.length})</h2>
        <ul>
          {inStock.map((product) => (
            <li key={product.id}>
              {product.name}: {product.inventory} units
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h2>Out of stock ({outOfStock.length})</h2>
        <ul>
          {outOfStock.map((product) => (
            <li key={product.id}>{product.name}</li>
          ))}
        </ul>
      </section>
    </main>
  )
}

